import java.io.IOException;
import java.util.StringTokenizer;

public class Main {

    private static long reflect(long n) {
        if (n == 0) return 9; // not used in this problem since n>=1
        long res = 0;
        long pow = 1;
        while (n > 0) {
            int d = (int)(n % 10);
            int rd = 9 - d;
            res += (long) rd * pow;
            pow *= 10;
            n /= 10;
        }
        // leading zeros automatically omitted by numeric representation
        return res;
    }

    private static long weight(long n) {
        return n * reflect(n);
    }

    private static long candidate(long x, long l, long r) {
        if (x < l) x = l;
        if (x > r) x = r;
        return weight(x);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        long l = fs.nextLong();
        long r = fs.nextLong();

        long ans = 0;

        // Always check boundaries
        ans = Math.max(ans, weight(l));
        ans = Math.max(ans, weight(r));

        // Strategy: numbers of form 10^k - 1 and 10^k within range are strong candidates
        // because they have digits 9...9 or 1000...0 which maximize product with reflection.
        long[] powers = new long[11];
        powers[0] = 1;
        for (int i = 1; i <= 10; i++) powers[i] = powers[i - 1] * 10;

        for (int i = 1; i <= 10; i++) {
