            if (nine >= l && nine <= r) {
                ans = Math.max(ans, weight(nine));
            }
            long ten = powers[i]; // 10, 100, 1000, ...
            if (ten >= l && ten <= r) {
                ans = Math.max(ans, weight(ten));
            }
        }

        // Additionally, check neighbors around these candidates within small window
        // to be safe for edge cases.
        for (int i = 1; i <= 10; i++) {
            long nine = powers[i] - 1;
            for (long d = -5; d <= 5; d++) {
                long x = nine + d;
                if (x >= l && x <= r) {
                    ans = Math.max(ans, weight(x));
                }
            }
            long ten = powers[i];
            for (long d = -5; d <= 5; d++) {
                long x = ten + d;
                if (x >= l && x <= r) {
                    ans = Math.max(ans, weight(x));
                }
            }
        }

        System.out.println(ans);
