        long res = 0;
        long pow = 1;
        while (n > 0) {
            int d = (int) (n % 10);
            int rd = 9 - d;
            res += (long) rd * pow;
            pow *= 10;
            n /= 10;
        }
        // remove leading zeros: they are naturally not produced in this construction
        return res;
    }

    private static long weight(long n) {
        return n * reflect(n);
    }

