        FastScanner fs = new FastScanner();
        long l = fs.nextLong();
        long r = fs.nextLong();

        long best = 0;

        // Check boundaries
        best = Math.max(best, weight(l));
        best = Math.max(best, weight(r));

        // For each possible digit length, consider the number consisting of all 9's
        // that lies in [l, r]. The product n * psi(n) is maximized near such borders.
        for (int len = 1; len <= 10; len++) {
            long nine = 0;
            for (int i = 0; i < len; i++) {
                nine = nine * 10 + 9;
            }
            if (nine >= l && nine <= r) {
                best = Math.max(best, weight(nine));
            }
            // also check nine-1 and nine+1 if they are in range, as maximum can be nearby
            if (nine - 1 >= l && nine - 1 <= r) {
                best = Math.max(best, weight(nine - 1));
            }
            if (nine + 1 >= l && nine + 1 <= r) {
                best = Math.max(best, weight(nine + 1));
            }
        }

        System.out.println(best);
    }

