import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    private static long reflect(long n) {
        if (n == 0) return 9;
        long res = 0;
        long pow = 1;
        while (n > 0) {
            int d = (int)(n % 10);
            int rd = 9 - d;
            res += (long) rd * pow;
            pow *= 10;
            n /= 10;
        }
        return res;
