        FastScanner fs = new FastScanner();
        long l = fs.nextLong();
        long r = fs.nextLong();

        long ans = 0;

        // Check endpoints
        ans = Math.max(ans, weight(l));
        ans = Math.max(ans, weight(r));

        // Generate candidates of form 10^k - 1 within [l, r]
        for (int k = 1; k <= 10; k++) {
            long val = (long) Math.pow(10, k) - 1;
            if (val < l || val > r) continue;
            ans = Math.max(ans, weight(val));
